CLEAN_EX1_PROBLEMS: Dict[str, str] = {}

CLEAN_EX1_ANS: Dict[str, str] = {}


def clean_ex1_problem(sec_num: str, raw_prob: str) -> str:
    """Returns a 100% pure Big Ideas Math textbook problem statement for Worked Example 1."""
    return CLEAN_EX1_PROBLEMS.get(sec_num, raw_prob)


def clean_ex1_ans(sec_num: str, raw_ans: str) -> str:
    """Returns a 100% pure Big Ideas Math textbook answer string for Worked Example 1."""
    return CLEAN_EX1_ANS.get(sec_num, raw_ans)


def clean_sheet_a_prompt(sec_num: str, p_num: int, raw_prompt: str) -> str:
    """Returns a clean, 100% textbook-terminology prompt for Practice Sheet A."""
    key = f"{sec_num}:{p_num}"
    if key in SHEET_A_PROMPT_OVERRIDES:
        return SHEET_A_PROMPT_OVERRIDES[key]
    s = raw_prompt.replace("Spot the Glitch:", "Error Analysis:")
    s = re.sub(r"\s*using\s+\[[^\]]+\](?:\s*\[[^\]]+\])*\.?", ".", s)
    s = re.sub(r"\s*on your SC-6!?", "", s)
    return s.strip()


