def get_starter_scaffold(sec_num: str, sheet: str, p_num: int) -> str:
    """Returns a problem-exact 1-line Step 1 Starter hint for Warm-Up Problems #1 and #2 on Practice A and B."""
    if p_num not in (1, 2):
        return ""
    quad = STARTER_SCAFFOLDS.get(sec_num)
    if not quad:
        return ""
    if sheet == "A":
        return quad[0] if p_num == 1 else quad[1]
    return quad[2] if p_num == 1 else quad[3]




